#include "ENGINE/Source/Event/event_internal.h"
#include <algorithm>

int EvtContext::IsCurrentContext()const{return EventInternal::current&&EventInternal::current->context==this;}
void*CSBasePriorityQueue::Dequeue(){if(m_data.empty())return nullptr;void*result=m_data.front();Remove(0);return result;}

unsigned IEvtTimerSet(HEVENTCONTEXT h,float timeout,EventHandler fn,void*p,EventGuidHandler g,std::uint64_t gp,void*gp2){auto*c=EventInternal::Resolve(h);if(!c||(!fn&&!g))return 0;std::lock_guard l(c->mutex);unsigned id=1;while(c->timers.contains(id))++id;EvtTimer t{id,std::chrono::steady_clock::now()+std::chrono::milliseconds(static_cast<unsigned>(std::max(0.0f,timeout)*1000.0f)),timeout,fn,p,g,gp,gp2};c->timers.emplace(id,t);return id;}
unsigned IEvtTimerSetAbsolute(HEVENTCONTEXT h,unsigned trigger,EventHandler fn,void*p,EventGuidHandler g,std::uint64_t gp,void*gp2){unsigned now=EventInternal::TimeMs();float seconds=static_cast<std::int32_t>(trigger-now)>0?(trigger-now)/1000.0f:0.0f;return IEvtTimerSet(h,seconds,fn,p,g,gp,gp2);}
void IEvtTimerKill(HEVENTCONTEXT h,unsigned id,EventHandler fn,const char*){auto*c=EventInternal::Resolve(h);if(!c)return;std::lock_guard l(c->mutex);auto i=c->timers.find(id);if(i!=c->timers.end()&&(!fn||i->second.handler==fn))c->timers.erase(i);}
double IEvtTimerGetRemaining(HEVENTCONTEXT h,unsigned id){auto*c=EventInternal::Resolve(h);if(!c)return 0;std::lock_guard l(c->mutex);auto i=c->timers.find(id);if(i==c->timers.end())return 0;return std::max(0.0,std::chrono::duration<double>(i->second.target-std::chrono::steady_clock::now()).count());}
unsigned IEvtTimerGetNextTime(HEVENTCONTEXT h,unsigned){auto*c=EventInternal::Resolve(h);if(!c)return ~0u;std::lock_guard l(c->mutex);unsigned result=~0u;auto current=std::chrono::steady_clock::now();for(auto&[id,t]:c->timers){auto ms=std::chrono::duration_cast<std::chrono::milliseconds>(t.target-current).count();result=std::min(result,static_cast<unsigned>(std::max<std::int64_t>(0,ms)));}return result;}
void IEvtTimerDispatch(HEVENTCONTEXT h){auto*c=EventInternal::Resolve(h);if(!c)return;auto old=EventInternal::current;EventInternal::current=EventInternal::CurrentOr(h);for(;;){EvtTimer timer{};bool found=false;{std::lock_guard l(c->mutex);auto now=std::chrono::steady_clock::now();auto selected=c->timers.end();for(auto i=c->timers.begin();i!=c->timers.end();++i)if(i->second.target<=now&&(selected==c->timers.end()||i->second.target<selected->second.target||(i->second.target==selected->second.target&&i->second.id<selected->second.id)))selected=i;if(selected!=c->timers.end()){timer=selected->second;c->timers.erase(selected);found=true;}}if(!found)break;EVENT_DATA_TIMER data{timer.timeout,EventInternal::TimeMs()};if(timer.handler)timer.handler(&data,timer.param);else if(timer.guidHandler)timer.guidHandler(&data,timer.guidParam,timer.guidParam2);}EventInternal::current=old;}
unsigned EventSetTimer(EventHandler f,void*p,float t){return IEvtTimerSet(EventInternal::current,t,f,p);}unsigned EventSetTimer(unsigned ms,EventHandler f,void*p){return IEvtTimerSet(EventInternal::current,ms/1000.0f,f,p);}unsigned EventSetTimer(EventGuidHandler f,std::uint64_t p,void*p2,float t){return IEvtTimerSet(EventInternal::current,t,nullptr,nullptr,f,p,p2);}unsigned EventSetTimer(unsigned ms,EventGuidHandler f,std::uint64_t p,void*p2){return IEvtTimerSet(EventInternal::current,ms/1000.0f,nullptr,nullptr,f,p,p2);}unsigned EventSetTimerAbsolute(unsigned t,EventHandler f,void*p){return IEvtTimerSetAbsolute(EventInternal::current,t,f,p);}unsigned EventSetTimerAbsolute(unsigned t,EventGuidHandler f,std::uint64_t p,void*p2){return IEvtTimerSetAbsolute(EventInternal::current,t,nullptr,nullptr,f,p,p2);}void EventKillTimer(unsigned id,EventHandler f,const char*n){IEvtTimerKill(EventInternal::current,id,f,n);}double EventGetRemainingTime(unsigned id){return IEvtTimerGetRemaining(EventInternal::current,id);}
